use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " A list of miniz failed status codes."] # [doc = ""] # [doc = " These are emitted as the [`Err`] side of a [`MZResult`] in the [`StreamResult`] returned from"] # [doc = " [`deflate::stream::deflate()`] or [`inflate::stream::inflate()`]."] # [repr (i32)] # [cfg_attr (not (feature = "rustc-dep-of-std") , derive (Hash , Debug))] # [derive (Copy , Clone , PartialEq , Eq)] pub enum MZError { # [doc = " Unused"] ErrNo = - 1 , # [doc = " General stream error."] # [doc = ""] # [doc = " See [`inflate::stream::inflate()`] docs for details of how it can occur there."] # [doc = ""] # [doc = " See [`deflate::stream::deflate()`] docs for how it can in principle occur there, though it's"] # [doc = " believed impossible in practice."] Stream = - 2 , # [doc = " Error in inflation; see [`inflate::stream::inflate()`] for details."] # [doc = ""] # [doc = " Not returned from [`deflate::stream::deflate()`]."] Data = - 3 , # [doc = " Unused"] Mem = - 4 , # [doc = " Buffer-related error."] # [doc = ""] # [doc = " See the docs of [`deflate::stream::deflate()`] or [`inflate::stream::inflate()`] for details"] # [doc = " of when it would trigger in the one you're using."] Buf = - 5 , # [doc = " Unused"] Version = - 6 , # [doc = " Bad parameters."] # [doc = ""] # [doc = " This can be returned from [`deflate::stream::deflate()`] in the case of bad parameters.  See"] # [doc = " [`TDEFLStatus::BadParam`][deflate::core::TDEFLStatus::BadParam]."] Param = - 10_000 , }